<script setup lang="ts">
import { computed, ref, onMounted } from 'vue'; import { useAuthStore } from '@/stores/auth'; import { fetchRoles, updateRole } from '@/api/retail'; import { track } from '@/monitor/tracker'; import type { Permission, RoleDefinition } from '@/types/domain'
const auth = useAuthStore(); const roles = ref<RoleDefinition[]>([]); const catalog = ref<{ code: string; label: string; group: string }[]>([]); const selectedId = ref('manager'); const saving = ref(false); const saved = ref(false)
const selected = computed(() => roles.value.find((r) => r.id === selectedId.value)); const groups = computed(() => [...new Set(catalog.value.map((p) => p.group))])
onMounted(async () => { if (!auth.token) return; const data = await fetchRoles(auth.token); roles.value = data.items.map((r) => ({ ...r, permissions: [...r.permissions] })); catalog.value = data.permissions })
function toggle(code: string) { if (!selected.value || selected.value.id === 'owner') return; const p = code as Permission; selected.value.permissions = selected.value.permissions.includes(p) ? selected.value.permissions.filter((x) => x !== p) : [...selected.value.permissions, p]; saved.value = false }
async function save() { if (!selected.value || !auth.token) return; saving.value = true; try { const updated = (await updateRole(selected.value.id, selected.value, auth.token)).item; const index = roles.value.findIndex((r) => r.id === updated.id); if (index >= 0) roles.value[index] = updated; saved.value = true; track('rbac_role_updated', { role: updated.id }); if (updated.id === auth.user?.role) { auth.accessReady = false; await auth.loadAccess() } } finally { saving.value = false } }
</script>
<template><div class="page-stack"><div class="page-heading"><div><span class="page-kicker">ACCESS CONTROL</span><h1 class="page-title">角色与权限</h1><p>配置会同步到服务端，并即时更新当前会话的权限菜单。</p></div><button v-permission="'rbac:manage'" class="btn-primary" :disabled="saving || selected?.id === 'owner'" @click="save">{{ saving ? '保存中…' : saved ? '已保存' : '保存更改' }}</button></div><section class="card permission-shell"><aside class="role-list"><button v-for="role in roles" :key="role.id" :class="{ active: selectedId === role.id }" @click="selectedId = role.id; saved = false"><span class="role-avatar">{{ role.name.slice(0,1) }}</span><span><strong>{{ role.name }}</strong><small>{{ role.userCount }} 位用户</small></span><i :class="role.enabled ? 'enabled' : ''"/></button></aside><div v-if="selected" class="permission-main"><div class="permission-head"><div><h2>{{ selected.name }}</h2><p>{{ selected.description }}</p></div><span v-if="selected.id === 'owner'" class="permission-badge">系统内置角色</span></div><div v-for="group in groups" :key="group" class="permission-group"><h3>{{ group }}</h3><label v-for="permission in catalog.filter((p) => p.group === group)" :key="permission.code" class="permission-row"><span><strong>{{ permission.label }}</strong><small>{{ permission.code }}</small></span><input type="checkbox" :checked="selected.permissions.includes(permission.code as Permission)" :disabled="selected.id === 'owner' || !auth.can('rbac:manage')" @change="toggle(permission.code)"/></label></div></div></section></div></template>
